    base := &replica.Replica{
        Logger: dlog.New("", false), N: n, F: 2, Id: id,
        Thrifty: true, Dreply: true,
        PeerWriters: make([]*bufio.Writer, n), Alive: make([]bool, n),
        PreferredPeerOrder: make([]int32, n),
